const API='/api';let token=localStorage.getItem('disha_token'),user=JSON.parse(localStorage.getItem('disha_user')||'null'),active='overview';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function api(url,opt={}){const isForm=opt.body instanceof FormData;const headers={...(isForm?{}:{'Content-Type':'application/json'}),...(token?{Authorization:'Bearer '+token}:{})};const r=await fetch(API+url,{...opt,headers:{...headers,...(opt.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Request failed');return d}
const asArray=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:Array.isArray(v?.rows)?v.rows:Array.isArray(v?.items)?v.items:[];
