function landingView(){$('#app').innerHTML=`<div class="landing"><header class="landing-nav"><div class="brand dark">DI<span>SHA</span></div><span>National Skilling Outcomes Platform</span><button class="mini-btn" id="landingLogin">Sign In</button></header><section class="landing-hero"><div class="landing-copy"><div class="gov-label">GOVERNMENT SKILLING & OUTCOME TRACKING</div><h1>Learn. Get skilled.<br><span>Build your future.</span></h1><p>DISHA connects learners with government-supported training programmes and tracks the journey from enrolment and certification to employment and long-term livelihood outcomes.</p><div class="landing-actions"><button class="btn" id="exploreRole">Get Started</button><button class="btn secondary" id="learnMore">How DISHA Works</button></div></div><div class="landing-stat"><b>One connected journey</b><div>Explore courses → Enrol → Train → Get certified → Build a career</div><small>Consent-based · Privacy conscious · Outcome focused</small></div></section><section class="role-section"><div><div class="gov-label">CHOOSE YOUR PORTAL</div><h2>How would you like to continue?</h2><p>Select your role to access the right DISHA portal.</p></div><div class="role-grid"><button class="role-card" data-role="trainee"><span>👨‍🎓</span><b>Student / Trainee</b><small>Explore all government courses, enrol yourself, manage your profile and track certificates & career outcomes.</small><em>Login or Register →</em></button><button class="role-card" data-role="admin"><span>🏛️</span><b>Government / Admin</b><small>Monitor programmes, providers, outcomes, verification, skill gaps and policy intelligence.</small><em>Admin Login →</em></button><button class="role-card" data-role="provider"><span>🏫</span><b>Training Provider</b><small>Manage batches, trainees, attendance, assessments, certificates and training outcomes.</small><em>Provider Login →</em></button><button class="role-card" data-role="employer"><span>🏢</span><b>Employer / Company</b><small>Connect hiring requirements with skilled candidates and verify employment outcomes.</small><em>Employer Login →</em></button></div></section><section class="solve-section" id="solve"><h2>What problem does DISHA solve?</h2><div class="solve-grid"><div><b>Training is not the final outcome</b><p>Traditional systems often stop at enrolment, attendance and certification. DISHA follows what happens after training.</p></div><div><b>Missing employment evidence</b><p>It captures self-reported outcomes, employer verification and follow-ups while keeping verification status transparent.</p></div><div><b>Better skilling decisions</b><p>Government can compare providers, courses, districts, skill gaps, retention and wage progression for evidence-based action.</p></div></div></section><footer>© DISHA · Government Skilling & Outcome Intelligence Platform</footer></div>`;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>authView(b.dataset.role));$('#landingLogin').onclick=()=>authView();$('#exploreRole').onclick=()=>document.querySelector('.role-section').scrollIntoView({behavior:'smooth'});$('#learnMore').onclick=()=>$('#solve').scrollIntoView({behavior:'smooth'})}
function authView(preferredRole=''){$('#app').innerHTML=`<div class="auth"><section class="hero"><div class="brand">DI<span>SHA</span></div><div class="eyebrow">NATIONAL SKILLING OUTCOMES PLATFORM</div><h1>From training to long-term livelihood outcomes.</h1><p>Choose a role, sign in securely and access the workspace built for your part in the skilling ecosystem.</p><button class="btn secondary back-btn" id="backHome">← Back to DISHA Home</button></section><section class="auth-card"><div class="form-card"><div class="brand dark">DI<span>SHA</span></div><p class="sub">Government Skilling & Outcome Intelligence Portal</p><div class="role-select"><label>Continue as</label><select id="roleSelect"><option value="">Select your portal</option><option value="trainee">Student / Trainee</option><option value="admin">Government / Admin</option><option value="provider">Training Provider</option><option value="employer">Employer / Company</option></select></div><div class="tabs"><button class="active" id="loginTab">Login</button><button id="registerTab">Trainee Registration</button></div><div id="authForm"></div></div></section></div>`;$('#roleSelect').value=preferredRole;const sync=()=>{const trainee=$('#roleSelect').value==='trainee';$('#registerTab').style.display=trainee?'block':'none';if(!trainee)showLogin()};$('#roleSelect').onchange=sync;sync();showLogin();$('#loginTab').onclick=showLogin;$('#registerTab').onclick=showRegister;$('#backHome').onclick=landingView}
function showLogin(){$('#loginTab').classList.add('active');$('#registerTab').classList.remove('active');$('#authForm').innerHTML=`<h2>Welcome back</h2><p class="sub">Sign in to the DISHA workspace selected above.</p><form id="loginForm"><div class="field"><label>Email</label><input type="email" name="email" required placeholder="you@example.com"></div><div class="field"><label>Password</label><input type="password" name="password" required placeholder="Enter password"></div><button class="btn full">Login to DISHA</button></form><div class="demo"><b>Demo accounts (password: disha123)</b><br>Government: admin@disha.gov.in<br>Provider: provider@disha.gov.in<br>Employer: employer@disha.gov.in<br>Trainee: aman@example.com</div><div id="msg"></div>`;$('#loginForm').onsubmit=login}
function showRegister(){$('#registerTab').classList.add('active');$('#loginTab').classList.remove('active');$('#authForm').innerHTML=`<h2>Create trainee record</h2><p class="sub">Create your learner account first. After login, browse and self-enrol in available government skill courses.</p><form id="regForm"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="form-grid"><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>District</label><input name="district"></div></div><div class="form-grid"><div class="field"><label>Gender</label><select name="gender"><option>Prefer not to say</option><option>Male</option><option>Female</option><option>Other</option></select></div><div class="field"><label>Age group</label><select name="ageGroup"><option>18-24</option><option>25-34</option><option>35+</option></select></div></div><div class="field"><label>Education</label><input name="education" placeholder="10th / 12th / Graduate / Diploma"></div><div class="field"><label>Password</label><input name="password" type="password" minlength="6" required></div><label class="check"><input type="checkbox" name="consent"> I consent to privacy-conscious longitudinal outcome tracking and authorized follow-ups.</label><button class="btn full">Create Trainee Account</button></form><div id="msg"></div>`;$('#regForm').onsubmit=register}
function message(t,b=false){const e=$('#msg');if(e)e.innerHTML=`<div class="notice ${b?'error':''}">${esc(t)}</div>`}
async function login(e){e.preventDefault();try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});token=d.token;user=d.user;localStorage.setItem('disha_token',token);localStorage.setItem('disha_user',JSON.stringify(user));render()}catch(x){message(x.message,true)}}
