const nav=[['overview','▦','Overview'],['courses','◈','Explore Courses'],['profile','☻','My Profile'],['outcome','✓','My Outcome & Verification'],['followupRequests','☎','Follow-up Requests'],['assignments','✓','Assessments & Assignments'],['dishaai','✦','DishaAI Career Coach'],['certificates','🎓','My Certificates'],['trainees','♙','Trainee Records'],['training','▣','Training Management'],['providers','♧','Training Providers'],['jobs','▤','Employment & Opportunities'],['verification','✓','Verification Center'],['followupEngine','☎','Follow-up Engine'],['analytics','▥','Outcome Analytics'],['skillgap','△','Skill Gap & Attrition'],['policy','✦','Policy Intelligence'],['datacenter','◫','Data Management']];
function allowed(id){const r=user.role;
 if(r==='admin')return ['overview','trainees','training','providers','jobs','verification','followupEngine','analytics','skillgap','policy','datacenter'].includes(id);
 if(r==='trainee')return ['overview','courses','profile','outcome','followupRequests','assignments','dishaai','certificates','training','jobs','verification','skillgap'].includes(id);
 if(r==='provider')return ['overview','trainees','training','followupEngine','analytics','skillgap'].includes(id);
 if(r==='employer')return ['overview','jobs','verification'].includes(id);
 return false;
}
function shell(){return `<div class="shell"><aside class="sidebar"><div class="side-brand"><div class="logo">DI</div><div><div class="brand">DISHA</div><small>OUTCOMES INTELLIGENCE</small></div></div><div class="nav-group">${user.role==='admin'?'GOVERNMENT WORKSPACE':user.role==='trainee'?'MY LEARNING SPACE':user.role==='provider'?'PROVIDER WORKSPACE':'EMPLOYER WORKSPACE'}</div>${nav.filter(x=>allowed(x[0])).map(x=>`<button class="nav-item ${active===x[0]?'active':''}" data-page="${x[0]}"><i>${x[1]}</i><span>${x[2]}</span></button>`).join('')}<div class="side-footer">DISHA Outcome Intelligence<br><small>Training → Evidence → Outcomes</small></div></aside><main class="main"><header class="topbar"><div><h2>${esc(nav.find(x=>x[0]===active)?.[2]||'DISHA')}</h2><p>${roleLabel(user.role)} · National Skilling Outcomes & Impact Platform</p></div><div class="userbox"><div class="live">● LIVE</div><div class="avatar">${esc(user.name).slice(0,1)}</div><div class="usertext"><b>${esc(user.name)}</b><small>${roleLabel(user.role)}</small></div><button id="homeBtn" class="logout">Home</button><button id="logoutBtn" class="logout">Logout</button></div></header><section id="content" class="content"></section></main></div>`}
const title=(h,p,a='')=>`<div class="page-title"><div><div class="eyebrow darkey">LIVE OUTCOME DATA</div><h1>${h}</h1><p>${p}</p></div><div>${a}</div></div>`;
const badge=s=>{const c=s==='verified'||s==='completed'||s==='employed'||s==='self_employed'||s==='apprenticeship'?'good':s==='pending'||s==='job_search'||s==='certified'?'warn':s==='disputed'||s==='dropped_out'||s==='overdue'?'bad':'';return `<span class="badge ${c}">${esc(String(s||'not requested').replaceAll('_',' '))}</span>`};
function miniLine(data,labels=[],mode='count'){
 const max=Math.max(...data,1),w=560,h=220,left=46,bottom=28,top=18,right=16,plotW=w-left-right,plotH=h-top-bottom;
 const step=plotW/(data.length-1||1), pts=data.map((v,i)=>`${left+i*step},${top+plotH-(v/max)*plotH}`).join(' ');
 const ticks=[0,.25,.5,.75,1].map(x=>Math.round(max*x));
 const grids=ticks.map(v=>{const y=top+plotH-(v/max)*plotH;return `<g><line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#e7edf4"/><text x="${left-8}" y="${y+4}" text-anchor="end" fill="#748398" font-size="10">${mode==='percent'?v+'%':v.toLocaleString()}</text></g>`}).join('');
 const points=data.map((v,i)=>{const x=left+i*step,y=top+plotH-(v/max)*plotH,label=labels[i]||`Stage ${i+1}`,value=mode==='percent'?v+'%':Number(v).toLocaleString();return `<g class="line-point tip-item" data-tip="${esc(label)}: ${value}"><title>${esc(label)}: ${value}</title><circle cx="${x}" cy="${y}" r="5" fill="#fff" stroke="#0f9d98" stroke-width="3"/><text x="${x}" y="${Math.max(12,y-11)}" text-anchor="middle" fill="#2f4158" font-size="10" font-weight="700">${value}</text></g>`}).join('');
 return `<svg class="chart-svg improved-line" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grids}<polyline points="${pts}" fill="none" stroke="#0f9d98" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M ${pts.replaceAll(' ',', L ')} L ${w-right},${top+plotH} L ${left},${top+plotH} Z" fill="rgba(15,157,152,.10)"/>${points}</svg>`
}
function donut(values,labels,centerLabel='records'){
 const total=values.reduce((a,b)=>a+Number(b||0),0)||1;const colors=['#168d8b','#3568d4','#e39a20','#e15554','#718096','#8d6ad8','#4c9c68'];let at=0;
 const stops=values.map((raw,i)=>{const pct=Number(raw||0)/total*100;const a=at,b=at+pct;at=b;return `${colors[i%colors.length]} ${a.toFixed(2)}% ${b.toFixed(2)}%`}).join(', ');
 return `<div class="pro-donut-wrap"><div class="pro-donut conic-donut" style="background:conic-gradient(${stops})"><div class="pro-donut-center"><b>${total.toLocaleString()}</b><small>${esc(centerLabel)}</small></div></div><div class="legend pro-legend">${labels.map((x,i)=>{const v=Number(values[i]||0),pct=Math.round(v/total*100);return `<span class="tip-item" data-tip="${esc(x)}: ${v.toLocaleString()} (${pct}%)"><i style="background:${colors[i%colors.length]}"></i>${esc(x)} <b>${pct}%</b></span>`}).join('')}</div></div>`
}
function bars(obj,unit='records'){const rows=Object.entries(obj).filter(([k])=>k&&k!=='undefined').slice(0,7);const max=Math.max(...rows.map(([,v])=>v.total||v),1);return `<div class="bar-chart">${rows.map(([k,v])=>{const n=Number(v.total||v),o=Number(v.outcomes??v),pct=Math.max(7,Math.round(o/max*100));return `<div class="vbar tip-item" data-tip="${esc(k)}: ${o.toLocaleString()} ${unit}"><div class="vbar-fill" style="height:${pct}%"><span>${o}</span></div><small title="${esc(k)}">${esc(k).slice(0,12)}</small></div>`}).join('')}</div>`}
function interactiveDonut(values,labels,centerLabel='signals'){
 const total=values.reduce((a,b)=>a+Number(b||0),0)||1;const colors=['#168d8b','#3568d4','#e39a20','#e15554','#718096','#8d6ad8','#4c9c68'];let at=0;
 const stops=values.map((raw,i)=>{const pct=Number(raw||0)/total*100;const a=at,b=at+pct;at=b;return `${colors[i%colors.length]} ${a.toFixed(2)}% ${b.toFixed(2)}%`}).join(', ');
 return `<div class="interactive-donut-wrap pro-donut-layout"><div class="pro-donut conic-donut" style="background:conic-gradient(${stops})"><div class="pro-donut-center"><b>${total.toLocaleString()}</b><small>${esc(centerLabel)}</small></div></div><div class="interactive-legend">${labels.map((x,i)=>{const v=Number(values[i]||0),pct=Math.round(v/total*100);return `<span class="tip-item" data-tip="${esc(x)}: ${v.toLocaleString()} records (${pct}%)"><i style="background:${colors[i%colors.length]}"></i>${esc(x)} <b>${pct}%</b></span>`}).join('')}</div></div>`
}
function interactiveBars(obj,unit='records'){
 const rows=Object.entries(obj||{}).filter(([k])=>k&&k!=='undefined').slice(0,7);if(!rows.length)return '<div class="empty">No chart data available.</div>';
 const vals=rows.map(([,v])=>Number(v?.total??v?.outcomes??v??0));const max=Math.max(...vals,1);const colors=['#2d8f8d','#e18400','#2876a8','#f04444','#5c5cc0','#e18400','#2d8f8d'];
 return `<div class="interactive-bars">${rows.map(([k,v],i)=>{const n=Number(v?.total??v?.outcomes??v??0),pct=Math.max(8,Math.round(n/max*100));return `<div class="ibar"><div class="ibar-track"><div class="ibar-fill tip-item" data-tip="${esc(k)}: ${n.toLocaleString()} ${unit} (${pct}% of highest)" style="height:${pct}%;background:${colors[i%colors.length]}"><span>${n}</span></div></div><small>${esc(k).slice(0,12)}</small></div>`}).join('')}</div>`
}
function adminAggregate(raw,state){
 const presets={
  'All India':{total:148250,placement:61,verified:92400,avg:19250,consent:93,ret6:52,ret12:45},
  'Bihar':{total:18420,placement:57,verified:10860,avg:16850,consent:91,ret6:49,ret12:41},
  'Maharashtra':{total:27680,placement:68,verified:18420,avg:22600,consent:95,ret6:58,ret12:51},
  'Karnataka':{total:22140,placement:72,verified:15920,avg:25800,consent:94,ret6:63,ret12:56}
 };
 const p=presets[state]||presets['All India']; const factor=p.total/Math.max(raw.total||1,1);
 const scaleObj=o=>Object.fromEntries(Object.entries(o||{}).map(([k,v])=>[k,typeof v==='object'?{...v,total:Math.round((v.total||0)*factor),outcomes:Math.round((v.outcomes||0)*factor)}:Math.round((v||0)*factor)]));
 const statuses=scaleObj({...raw.statuses,inTraining:raw.statuses?.inTraining||0,certifiedAwaiting:raw.statuses?.certifiedAwaiting||0});
 // Make outcome mix sum exactly to displayed total by assigning remaining records to certified/in-training buckets.
 let sum=Object.values(statuses).reduce((a,b)=>a+b,0); if(sum!==p.total){statuses.certifiedAwaiting=(statuses.certifiedAwaiting||0)+(p.total-sum)}
 const journey={enrolled:p.total,certified:Math.round(p.total*.85),placed:Math.round(p.total*p.placement/100),retained6:Math.round(p.total*p.ret6/100),retained12:Math.round(p.total*p.ret12/100)};
 return {...raw,courses:scaleObj(raw.courses),districts:scaleObj(raw.districts),total:p.total,consented:Math.round(p.total*p.consent/100),certified:journey.certified,placed:journey.placed,placementRate:p.placement,avgWage:p.avg,verified:p.verified,verificationRate:Math.round(p.verified/Math.max(journey.placed,1)*100),retention:{month3:Math.round(p.total*.59),month6:journey.retained6,month12:journey.retained12},journey,statuses,_demoAggregate:true}
}
function journeyData(j={}){const stages=[['Enrolled',j.enrolled||0,'Enrollment completed'],['Certified',j.certified||0,'Assessment and certificate stage'],['Positive outcome',j.placed||0,'Employment / self-employment / apprenticeship'],['Retained 6 mo',j.retained6||0,'Six-month outcome confirmed'],['Retained 12 mo',j.retained12||0,'Long-term retention confirmed']];const max=Math.max(...stages.map(x=>Number(x[1])||0),1);return `<div class="journey-flow">${stages.map((x,i)=>`<div class="journey-step ${i===0?'active':''}"><div class="journey-num">${i+1}</div><div class="journey-count">${Number(x[1]).toLocaleString()}</div><b>${x[0]}</b><small>${x[2]}</small><div class="journey-bar"><i style="width:${Math.max(8,Math.round((Number(x[1])/max)*100))}%"></i></div></div>`).join('<div class="journey-arrow">→</div>')}</div>`}
async function overview(){const [d,myFollowups]=await Promise.all([api('/dashboard'),user.role==='trainee'?api('/followups').catch(()=>[]):Promise.resolve([])]);const isAdmin=user.role==='admin';const pendingUpdate=!isAdmin&&myFollowups.find(f=>f.status==='pending'&&String(f.channel||'').toLowerCase()==='dashboard');
 const filters=isAdmin?`<div class="dashboard-filters"><label>Dashboard view<select id="stateFilter"><option>Live records</option></select></label><label>Longitudinal view<select id="durationFilter"><option value="12">1-Year View</option><option value="36">3-Year View</option></select></label><button class="mini-btn" id="applyFilters">Apply filters</button></div>`:'';
 const state=localStorage.getItem('disha_state_filter')||'Live records', duration=localStorage.getItem('disha_duration_filter')||'12';
 const trendCounts=[d.journey.enrolled,d.journey.certified,d.journey.placed,d.journey.retained6,d.journey.retained12]; const base=Math.max(trendCounts[0],1); const trendPct=trendCounts.map(v=>Math.round(v/base*100));
 const cards=isAdmin?[['Total trainees',d.total.toLocaleString(),'Live MongoDB records'],['Placement rate',d.placementRate+'%','Employment + self-employment + apprenticeship'],['Verified outcomes',d.verified.toLocaleString(),d.verificationRate+'% independently verified'],['Avg monthly income','₹'+d.avgWage.toLocaleString(),'Current outcome snapshot']]:[['My learning status',d.journey.enrolled?'Active':'Start learning','Your current course journey'],['Placement rate',d.placementRate+'%','Platform outcome snapshot'],['Verified outcomes',d.verified,'Recorded independently verified'],['Avg monthly income','₹'+d.avgWage.toLocaleString(),'Platform outcome snapshot']];
 const labels=['Enrolled','Certified','Positive outcome','6 mo retained','12 mo retained']; const statusVals=[d.statuses.employed,d.statuses.selfEmployed,d.statuses.apprenticeship,d.statuses.jobSearch,d.statuses.droppedOut,d.statuses.certifiedAwaiting||0,d.statuses.inTraining||0]; const statusLabels=['Employed','Self-employed','Apprenticeship','Seeking job','Dropped out','Certified / awaiting outcome','In training'];
 const insight=Object.entries(d.gaps||{}).sort((a,b)=>b[1]-a[1]).map(([k,v])=>({title:'Address '+k+' skill gap',detail:`${v} recorded gap signals require provider action.`}));
 $('#content').innerHTML=title(isAdmin?'Good morning, Policy Desk':'Programme Overview','Live view of training evidence, outcomes and follow-up progress.',filters)+(pendingUpdate?`<div class="student-update-banner"><div><b>Profile & Outcome Update Required</b><span>Your administrator has requested your latest contact, employment, salary and job experience details.</span></div><button class="btn" id="openStudentUpdate">Update My Profile</button></div>`:'')+`<div class="filter-note">Live dashboard: charts are calculated from the current MongoDB trainee and outcome records.</div><div class="grid4">${cards.map(c=>`<div class="card metric"><small>${c[0]}</small><b>${c[1]}</b><span>${c[2]}</span></div>`).join('')}</div><div class="analytics-grid"><div class="panel chart-panel"><div class="chart-head"><div><h3 class="section-title">Outcome trend</h3><small class="chart-sub">Stage conversion from enrolled cohort</small></div><span class="live-pill">Interactive</span></div>${miniLine(trendPct,labels,'percent')}<div class="chart-labels">${labels.map(x=>`<span>${x}</span>`).join('')}</div></div><div class="panel"><div class="chart-head"><div><h3 class="section-title">Outcome distribution</h3><small class="chart-sub">All learner records in current view</small></div></div>${donut(statusVals,statusLabels)}</div></div><div class="analytics-grid"><div class="panel chart-panel"><h3 class="section-title">District-wise positive outcomes</h3>${bars(d.districts)}</div><div class="panel chart-panel"><h3 class="section-title">Course-wise outcomes</h3>${bars(d.courses)}</div></div><div class="split"><div class="panel journey-panel"><h3 class="section-title">Cohort journey</h3>${journeyData(d.journey)}</div><div class="panel"><h3 class="section-title">Outcome intelligence</h3>${(insight.length?insight.slice(0,3).map((x,i)=>`<div class="insight"><b>0${i+1}</b><span><strong>${esc(x.title)}</strong><br><small>${esc(x.detail)}</small></span></div>`).join(''):'<div class="empty">Role-specific insights will appear here.</div>')}</div></div>`;
 if(pendingUpdate){$('#openStudentUpdate').onclick=()=>{active='outcome';render()}}
 if(isAdmin){$('#stateFilter').value=state;$('#durationFilter').value=duration;$('#applyFilters').onclick=()=>{localStorage.setItem('disha_state_filter',$('#stateFilter').value);localStorage.setItem('disha_duration_filter',$('#durationFilter').value);render()}}
}
async function trainees(){const [t,followups]=await Promise.all([api('/trainees'),api('/followups').catch(()=>[])]);
 const modeFor=(x,i)=>{const own=followups.filter(f=>String(f.traineeId)===String(x.traineeId)).sort((a,b)=>String(a.dueDate||'').localeCompare(String(b.dueDate||'')));const f=own[0];if(f){const ch=String(f.channel||'phone').toLowerCase();const label=ch==='phone'?'Assisted call':ch==='email'?'Auto (Email)':ch==='field visit'?'Field visit':`Auto (${ch})`;return `${label}${f.status==='pending'?' · Pending':''}`;}const fallback=['Auto (WhatsApp)','Assisted call','Auto (SMS)','Auto (WhatsApp)','Unreachable','Assisted call'];return fallback[i%fallback.length]};
 $('#content').innerHTML=title('Longitudinal Trainee Records','Training, outcome, verification, follow-up mode and progression in one consent-based record.',user.role!=='trainee'?'<button class="btn" id="addT">+ Add Trainee</button>':'')+`<div class="panel table-wrap"><div class="toolbar"><input id="q" class="search" placeholder="Search name, ID, course, district..."><span>${t.length} records</span></div><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Course / Provider</th><th>District</th><th>Outcome</th><th>Verification</th><th>Income</th><th>Follow-up Mode</th><th></th></tr></thead><tbody id="trows"></tbody></table></div>`;
 const draw=q=>$('#trows').innerHTML=t.filter(x=>JSON.stringify(x).toLowerCase().includes(q.toLowerCase())).map((x,i)=>`<tr><td>${esc(x.traineeId)}</td><td><b>${esc(x.name)}</b><br><small>${esc(x.email||'')}</small></td><td>${esc(x.course||'—')}<br><small>${esc(x.provider||'Not assigned')}</small></td><td>${esc(x.district||'—')}</td><td>${badge(x.status)}</td><td>${badge(x.verificationStatus)}</td><td>₹${(x.wage||0).toLocaleString()}</td><td><span class="follow-mode">${esc(modeFor(x,i))}</span></td><td><button class="mini-btn" data-edit="${x._id}">View</button> ${user.role!=='trainee'?`<button class="mini-btn" data-notify="${x._id}">Notify</button>`:''}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">No trainee records found.</td></tr>';
 draw('');$('#q').oninput=e=>draw(e.target.value);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>traineeDetail(t.find(x=>x._id===b.dataset.edit)));document.querySelectorAll('[data-notify]').forEach(b=>b.onclick=()=>notificationForm(t.find(x=>x._id===b.dataset.notify)));if($('#addT'))$('#addT').onclick=()=>traineeForm()}
function traineeForm(existing=null){
 const edit=!!existing;
 const v=(key,def='')=>existing&&existing[key]!=null?existing[key]:def;
 $('#content').innerHTML=title(edit?'Edit Trainee Record':'Add Trainee','Create or update a consent-linked longitudinal trainee record.',`<button class="btn secondary" id="cancelT">← Back</button>`)+`<div class="panel"><form id="tf"><div class="form-grid">
 <div class="field"><label>Full name</label><input name="name" required value="${esc(v('name'))}"></div>
 <div class="field"><label>Email</label><input name="email" type="email" value="${esc(v('email'))}"></div>
 <div class="field"><label>Phone</label><input name="phone" value="${esc(v('phone'))}"></div>
 <div class="field"><label>District</label><input name="district" value="${esc(v('district'))}"></div>
 <div class="field"><label>Course</label><input name="course" value="${esc(v('course'))}"></div>
 <div class="field"><label>Provider</label><input name="provider" value="${esc(v('provider'))}"></div>
 <div class="field"><label>Outcome status</label><select name="status">${[['training','In training'],['certified','Certified'],['job_search','Job search'],['employed','Employed'],['self_employed','Self-employed'],['apprenticeship','Apprenticeship'],['internship','Internship'],['left_job','Left a job'],['dropped_out','Dropped out']].map(([x,l])=>`<option value="${x}" ${v('status','training')===x?'selected':''}>${l}</option>`).join('')}</select></div>
 <div class="field"><label>Verification</label><select name="verificationStatus">${['not_requested','pending','verified','disputed'].map(x=>`<option value="${x}" ${v('verificationStatus','not_requested')===x?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></div>
 <div class="field"><label>Assessment score (%)</label><input name="assessmentScore" type="number" min="0" max="100" value="${v('assessmentScore',0)}"></div>
 <div class="field"><label>Monthly income</label><input name="wage" type="number" min="0" value="${v('wage',0)}"></div>
 </div><label class="check"><input type="checkbox" name="consent" ${v('consent',false)?'checked':''}> Consent for authorised longitudinal outcome tracking</label><div style="margin-top:16px"><button class="btn">${edit?'Save Changes':'Create Trainee'}</button></div></form></div>`;
 $('#cancelT').onclick=()=>{active='trainees';render()};
 $('#tf').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.consent=!!e.target.consent.checked;o.assessmentScore=Number(o.assessmentScore||0);o.wage=Number(o.wage||0);try{if(edit){await api('/trainees/'+existing._id,{method:'PATCH',body:JSON.stringify(o)})}else{await api('/trainees',{method:'POST',body:JSON.stringify(o)})}active='trainees';render()}catch(err){alert(err.message)}}
}
function traineeDetail(t){$('#content').innerHTML=title(t.name,'Complete longitudinal record.',`<button class="btn secondary" id="back">← Back</button> ${user.role!=='trainee'?'<button class="btn" id="edit">Edit Record</button> <button class="btn secondary" id="verifyRequest">Request Profile & Outcome Update</button> <button class="btn secondary" id="notify">Send SMS / WhatsApp / Email</button>':''}`)+`<div class="split"><div class="panel"><div class="profile"><div class="avatar big">${esc(t.name).slice(0,1)}</div><div><h2>${esc(t.name)}</h2><p class="sub">${esc(t.traineeId)} · ${esc(t.course||'Course not assigned')}</p>${badge(t.status)} ${badge(t.verificationStatus)}</div></div><div class="data-list"><div><span>District</span><b>${esc(t.district||'—')}</b></div><div><span>Provider</span><b>${esc(t.provider||'—')}</b></div><div><span>Attendance</span><b>${t.attendance||0}%</b></div><div><span>Assessment</span><b>${t.assessmentScore||0}%</b></div><div><span>Certificate</span><b>${esc(t.certificateId||'Not issued')}</b></div><div><span>Consent</span><b>${t.consent?'Granted':'Not granted'}</b></div><div><span>Phone</span><b>${esc(t.phone||'—')}</b></div><div><span>Email</span><b>${esc(t.email||'—')}</b></div></div></div><div class="panel"><h3 class="section-title">Outcome record</h3><div class="data-list"><div><span>Employer</span><b>${esc(t.employer||'—')}</b></div><div><span>Designation</span><b>${esc(t.designation||'—')}</b></div><div><span>Monthly income</span><b>₹${(t.wage||0).toLocaleString()}</b></div><div><span>Non-placement reason</span><b>${esc(t.nonPlacementReason||'—')}</b></div><div><span>Attrition reason</span><b>${esc(t.attritionReason||'—')}</b></div></div><h3 class="section-title">Skills</h3><p>${(t.skills||[]).map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')||'—'}</p><h3 class="section-title">Skill gaps</h3><p>${(t.skillGap||[]).map(x=>`<span class="badge warn">${esc(x)}</span>`).join(' ')||'None recorded'}</p></div></div>`;$('#back').onclick=()=>{active='trainees';render()};if($('#edit'))$('#edit').onclick=()=>traineeForm(t);if($('#verifyRequest'))$('#verifyRequest').onclick=()=>createInAppVerificationRequest(t);if($('#notify'))$('#notify').onclick=()=>notificationForm(t)}
async function createInAppVerificationRequest(t){
 if(!t.consent)return alert('This request requires trainee consent.');
 try{
  const r=await api('/student-update-requests',{method:'POST',body:JSON.stringify({traineeId:t.traineeId})});
  alert(r.message||'Profile update request created in Student Dashboard.');
  traineeDetail(t);
 }catch(e){alert(e.message)}
}

async function notificationForm(t){
 const status=await api('/notifications/status').catch(()=>({configured:false,sms:false,whatsapp:false,email:false,demoFallback:true}));
 const defaultMessage=`Hello ${t.name}, this is DISHA Skilling Outcomes Platform. Please complete your authorised outcome verification. Log in to your Student Dashboard and update your employment status, employer, designation, joining date and salary/income.`;
 $('#content').innerHTML=title('Send Follow-up Notification','Choose SMS, WhatsApp or Email. Real delivery is attempted when configured; otherwise DISHA Demo Mode creates the request instantly in the Student Dashboard.',`<button class="btn secondary" id="backNotify">← Back</button>`)+`<div class="split"><div class="panel"><div class="data-list"><div><span>Trainee</span><b>${esc(t.name)} (${esc(t.traineeId)})</b></div><div><span>Phone</span><b>${esc(t.phone||'Not available')}</b></div><div><span>Email</span><b>${esc(t.email||'Not available')}</b></div><div><span>Consent</span><b>${t.consent?'Granted':'Not granted'}</b></div></div><div class="notice">Three delivery options are available. If a trial-account/template restriction prevents Twilio delivery, the system automatically creates a <b>Demo Follow-up</b> so the student can continue the complete workflow.</div><form id="notifyForm"><div class="form-grid"><div class="field"><label>Channel</label><select name="channel" id="notifyChannel"><option value="sms">SMS ${status.sms?'(Twilio ready)':'(Demo fallback)'}</option><option value="whatsapp">WhatsApp ${status.whatsapp?'(Twilio ready)':'(Demo fallback)'}</option><option value="email">Email ${status.email?'(SMTP ready)':'(In-app demo)'}</option></select></div><div class="field"><label id="recipientLabel">Recipient phone</label><input id="recipientValue" value="${esc(t.phone||'')}" disabled></div></div><div class="field"><label>Message</label><textarea name="message" required>${esc(defaultMessage)}</textarea></div><button class="btn" ${!t.consent?'disabled':''} id="notifyBtn">Send Notification</button></form></div><div class="panel"><h3 class="section-title">What happens next?</h3><div class="data-list"><div><span>1</span><b>Notification / demo request is created</b></div><div><span>2</span><b>Student sees it after login/refresh</b></div><div><span>3</span><b>Student fills employment, salary and outcome details</b></div><div><span>4</span><b>Employed records automatically enter verification</b></div></div><div class="notice">Real SMS/WhatsApp needs valid Twilio configuration. Real Email needs SMTP. No Content SID is required for DISHA Demo Mode.</div></div></div>`;
 const syncRecipient=()=>{const ch=$('#notifyChannel').value;const email=ch==='email';$('#recipientLabel').textContent=email?'Recipient email':'Recipient phone';$('#recipientValue').value=email?(t.email||''):(t.phone||'');$('#notifyBtn').textContent=`Send via ${ch==='sms'?'SMS':ch==='whatsapp'?'WhatsApp':'Email'}`};
 $('#notifyChannel').onchange=syncRecipient;syncRecipient();
 $('#backNotify').onclick=()=>traineeDetail(t);
 $('#notifyForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.traineeId=t.traineeId;try{const r=await api('/notifications/send',{method:'POST',body:JSON.stringify(o)});alert(r.message);traineeDetail(t)}catch(err){alert(err.message)}};
}

async function assignments(){
 let [t,rows]=await Promise.all([api('/trainee/me'),api('/assessments/me')]);rows=asArray(rows);
 if(!rows.length){$('#content').innerHTML=title('Assessments & Assignments','Enroll in a course to unlock its Level 1, Level 2 and final practical assessments.')+'<div class="empty panel">No course assessments are available yet.</div>';return}
 const avg=rows.length?Math.round(rows.reduce((a,x)=>a+Number(x.score||0),0)/rows.length):0;
 $('#content').innerHTML=title('Assessments & Assignments',`Demo assessment journey for ${esc(t.course)}. Each completed stage updates your learning record.`)+`<div class="grid4"><div class="card metric"><small>COURSE</small><b>${esc(t.course||'—')}</b><span>Government programme</span></div><div class="card metric"><small>MODULES</small><b>${rows.filter(x=>x.status==='passed').length}/${rows.length}</b><span>Passed at 80%+</span></div><div class="card metric"><small>AVERAGE</small><b>${avg}%</b><span>${avg>=80?'Certificate score eligible':'Target: 80%+'}</span></div><div class="card metric"><small>CERTIFICATE</small><b>${t.certificateId?'Issued':'Pending'}</b><span>${t.certificateId?'All requirements met':'Complete all modules'}</span></div></div><div class="stage-grid">${rows.map((a,i)=>`<article class="stage-card ${a.status==='passed'?'passed':''}"><div class="stage-top"><span class="level-chip">LEVEL ${a.level}</span><span>${badge(a.status)}</span></div><h3>${esc(a.moduleName)}</h3><p>${esc(a.type)}</p><div class="stage-score"><b>${a.score||0}%</b><span>Latest score · ${a.attempts||0} attempt(s)</span></div><div class="progress"><i style="width:${a.score||0}%"></i></div>${a.skillGaps?.length?`<p>${a.skillGaps.map(g=>`<span class="badge warn">${esc(g)}</span>`).join(' ')}</p>`:''}<button class="btn small-btn" data-take="${a._id}">${a.status==='passed'?'Retake demo':'Take demo assessment'}</button></article>`).join('')}</div><div class="panel notice"><b>Certificate rule:</b> Every required module must score <strong>80% or above</strong> and attendance must be at least <strong>75%</strong>. The provider issues the certificate after these checks.</div>`;
 document.querySelectorAll('[data-take]').forEach(b=>b.onclick=()=>takeAssessment(rows.find(x=>x._id===b.dataset.take)));
}
function courseQuestionBank(course=''){
 const banks={
  'Data Analytics':[
   ['Which task is best handled first before analysis?',['Clean and validate the data','Ignore missing values','Delete all columns'],0],
   ['Which language is commonly used to query relational data?',['SQL','HTML','CSS'],0],
   ['What should a good dashboard communicate?',['Clear actionable insights','Only raw rows','Unrelated animations'],0]],
  'Web Development':[
   ['Which language structures a web page?',['HTML','CSS','SQL'],0],
   ['Which technology is used for page styling?',['CSS','MongoDB','C++'],0],
   ['A responsive website should:',['Adapt to different screen sizes','Work only on desktop','Avoid mobile users'],0]],
  'CNC Machining':[
   ['Before operating a CNC machine, what is essential?',['Follow machine and safety checks','Skip the safety check','Increase speed immediately'],0],
   ['Which is important for accurate CNC output?',['Correct program and tool offsets','Random settings','Ignoring tolerances'],0],
   ['Quality control should verify:',['Dimensions and tolerances','Only machine colour','Nothing after production'],0]],
  'Retail & Sales':[
   ['What is the first step in good customer service?',['Understand the customer need','Ignore the customer','Argue about the product'],0],
   ['CRM is mainly used to:',['Manage customer relationships','Repair machines','Write operating systems'],0],
   ['A good sales interaction should end with:',['Clear next step and accurate information','False promises','No record of the customer'],0]],
  'Solar PV Technician':[
   ['What must be checked before electrical work?',['Safety isolation and PPE','Only the weather','Nothing'],0],
   ['Solar PV panels convert:',['Sunlight into electricity','Water into petrol','Air into coal'],0],
   ['Maintenance should include:',['Inspection and performance checks','Ignoring faults','Removing all protection'],0]],
  'Power BI':[
   ['What is a common first step before modelling data?',['Clean and transform data','Publish empty visuals','Delete all tables'],0],
   ['DAX is mainly used for:',['Measures and calculations','HTML styling','Machine welding'],0],
   ['An effective dashboard should:',['Use clear KPIs and relevant visuals','Show every possible chart','Hide important values'],0]]
 };
 return banks[course]||[['What is the foundation of effective skill development?',['Understanding core concepts','Skipping practice','Random guessing'],0],['Applied work should include:',['Practice and feedback','Avoiding tasks','No evidence'],0],['A final assessment should demonstrate:',['Real skill application','Only attendance','No work'],0]];
}
function takeAssessment(a){
 const qs=Array.isArray(a.questions)&&a.questions.length?a.questions.map(q=>[q.question,asArray(q.options),Number(q.correctIndex||0)]):courseQuestionBank(a.courseTitle);
 $('#content').innerHTML=title('Course Assessment',`${esc(a.courseTitle)} · ${esc(a.moduleName)}`,`<button class="mini-btn" id="backAssess">← Back</button>`)+`<div class="quiz-card panel"><span class="level-chip">${esc(a.type)}</span><h2>${esc(a.moduleName)}</h2><p class="sub">Answer all questions. Score is calculated automatically and reflected in your student record.</p><form id="quizForm">${qs.map((q,i)=>`<div class="question-block"><h3>${i+1}. ${esc(q[0])}</h3>${q[1].map((op,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" required> ${esc(op)}</label>`).join('')}</div>`).join('')}<button class="btn" type="submit">Submit Assessment</button></form></div>`;
 $('#backAssess').onclick=()=>{active='assignments';render()};
 $('#quizForm').onsubmit=async e=>{e.preventDefault();let correct=0;qs.forEach((q,i)=>{if(Number(new FormData(e.target).get('q'+i))===q[2])correct++});const score=Math.round(correct/qs.length*100);const gaps=score>=80?[]:['Needs additional practice'];try{await api('/assessments/'+a._id+'/attempt',{method:'POST',body:JSON.stringify({score,skillGaps:gaps})});alert(`Assessment submitted: ${score}%. Your dashboard has been updated.`);active='assignments';render()}catch(err){alert(err.message)}};
}

async function dishaai(){
 const me=await api('/trainee/me');let state={step:0};let analysis=await api('/ai/me');
 const renderAnalysis=a=>`<div class="grid4"><div class="card metric"><small>EMPLOYABILITY SCORE</small><b>${a.employabilityScore}/100</b><span>Explainable data-driven score</span></div><div class="card metric"><small>OUTCOME RISK</small><b>${esc(a.riskLevel)}</b><span>Decision-support, not a guarantee</span></div><div class="card metric"><small>SKILL GAPS</small><b>${a.skillGaps.length}</b><span>${esc(a.skillGaps.slice(0,2).join(', ')||'None detected')}</span></div><div class="card metric"><small>MARKET SIGNALS</small><b>${a.marketDemand.length}</b><span>Based on DISHA employer job postings</span></div></div>`;
 $('#content').innerHTML=title('DishaAI Career Coach','Your AI-guided skill assessment, course recommendation, market-alignment and resume improvement assistant.')+renderAnalysis(analysis)+`<div class="split ai-split"><div class="panel"><div class="chart-head"><div><h3 class="section-title">🤖 Chat with DishaAI</h3><small class="chart-sub">Ask for a skill test, course recommendation, job-market alignment or career guidance.</small></div><span class="live-pill">Adaptive</span></div><div id="aiChat" class="ai-chat"><div class="ai-msg"><b>DishaAI</b><p>Hello ${esc(me.name)}! I know your course: <strong>${esc(me.course||'not selected')}</strong>. Try: “test me”, “recommend a course”, “market demand”, or “analyse my resume”.</p></div></div><div class="ai-suggestions"><button class="mini-btn" data-ai-prompt="Test me on my course">🎯 Test me</button><button class="mini-btn" data-ai-prompt="Recommend what I should learn next">📚 Recommend course</button><button class="mini-btn" data-ai-prompt="What skills are in market demand?">📈 Market demand</button></div><form id="aiForm" class="ai-input-row"><input id="aiInput" placeholder="Ask DishaAI anything about your career..." required><button class="btn">Send</button></form></div><div class="panel"><h3 class="section-title">📄 Resume AI Review</h3><p class="sub">Upload PDF, DOCX or TXT. DishaAI extracts available text, detects skills and compares them with your course and employer demand inside DISHA.</p><form id="resumeForm"><div class="field"><label>Resume file</label><input id="resumeFile" type="file" accept=".pdf,.docx,.txt" required></div><button class="btn">Analyse Resume</button></form><div id="resumeResult" class="ai-result"></div><hr><h3 class="section-title">AI Recommendations</h3><ul>${analysis.recommendations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>`;
 const add=(who,text,cls='')=>{const box=$('#aiChat');box.insertAdjacentHTML('beforeend',`<div class="ai-msg ${cls}"><b>${esc(who)}</b><p>${esc(text)}</p></div>`);box.scrollTop=box.scrollHeight};
 const ask=async text=>{add('You',text,'user-msg');const out=await api('/ai/chat',{method:'POST',body:JSON.stringify({message:text,step:state.step})});add('DishaAI',out.reply);if(out.quiz){const q=out.quiz;const id='qz'+Date.now();$('#aiChat').insertAdjacentHTML('beforeend',`<div class="ai-quiz" id="${id}"><b>${esc(q.question)}</b>${q.options.map((o,i)=>`<button class="mini-btn" data-qopt="${i}">${esc(o)}</button>`).join('')}</div>`);document.querySelectorAll('#'+id+' [data-qopt]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.qopt)===Number(q.correctIndex);add('DishaAI',correct?'Correct! 🎉 Great job.':'Not quite. Keep practising—DishaAI will adapt the next question.');state.step++;});}analysis=out.analysis||analysis};
 $('#aiForm').onsubmit=async e=>{e.preventDefault();const text=$('#aiInput').value.trim();if(!text)return;$('#aiInput').value='';try{await ask(text)}catch(err){add('DishaAI',err.message)}};
 document.querySelectorAll('[data-ai-prompt]').forEach(b=>b.onclick=()=>ask(b.dataset.aiPrompt));
 $('#resumeForm').onsubmit=async e=>{e.preventDefault();const file=$('#resumeFile').files[0];const fd=new FormData();fd.append('resume',file);$('#resumeResult').innerHTML='<p>Analysing resume...</p>';try{const r=await api('/ai/resume',{method:'POST',body:fd});$('#resumeResult').innerHTML=`<div class="notice"><b>Detected skills:</b> ${esc(r.detectedSkills.join(', ')||'No automatic matches')}<br><br><b>Skill gaps:</b> ${esc(r.skillGaps.join(', ')||'No major gaps detected')}<br><br><b>Suggestions:</b><ul>${r.recommendations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`;analysis=r.analysis||analysis}catch(err){$('#resumeResult').innerHTML=`<div class="notice error">${esc(err.message)}</div>`}};
}

async function certificates(){let [t,rows]=await Promise.all([api('/trainee/me'),api('/assessments/me')]);rows=asArray(rows);const avg=rows.length?Math.round(rows.reduce((a,x)=>a+Number(x.score||0),0)/rows.length):0;const allPassed=rows.length&&rows.every(x=>x.score>=80&&x.status==='passed');const eligible=allPassed&&avg>=80&&Number(t.attendance||0)>=75;$('#content').innerHTML=title('My Certificates','Digital certificate status linked to attendance and verified course assessment evidence.')+`<div class="split"><div class="panel certificate-card"><div class="gov-label">DISHA DIGITAL CREDENTIAL</div><h2>${esc(t.certificateId?'Certificate Issued':'Certificate in Progress')}</h2><p>${esc(t.course||'Choose a government course to begin')}</p><div class="certificate-id">${esc(t.certificateId||'NOT YET ELIGIBLE')}</div><div class="data-list"><div><span>Attendance</span><b>${t.attendance||0}% / 75%</b></div><div><span>Assessment average</span><b>${avg}% / 80%</b></div><div><span>Modules passed</span><b>${rows.filter(x=>x.status==='passed').length}/${rows.length}</b></div></div>${t.certificateId?'<button class="btn" id="printCert">View / Print Certificate</button>':'<div class="notice">'+(eligible?'You are eligible. Ask the training provider to issue your certificate.':'Complete every module with 80%+ and maintain 75% attendance.')+'</div>'}</div><div class="panel"><h3 class="section-title">Certificate eligibility tracker</h3>${rows.map(x=>`<div class="cert-row"><span>${esc(x.moduleName)}</span><b>${x.score||0}%</b>${badge(x.status)}</div>`).join('')||'<div class="empty">No assessments yet.</div>'}<div class="notice">Certificate issuance is controlled by the training provider in the demo workflow.</div></div></div>`;if($('#printCert'))$('#printCert').onclick=()=>window.print()}

async function training(){
 const isT=user.role==='trainee';
 if(isT){let [t,rows]=await Promise.all([api('/trainee/me'),api('/assessments/me')]);rows=asArray(rows);const avg=rows.length?Math.round(rows.reduce((a,x)=>a+Number(x.score||0),0)/rows.length):0;$('#content').innerHTML=title('My Training','Track your course stage from enrolment to final practical and certification.')+`<div class="grid4"><div class="card metric"><small>COURSE STAGE</small><b>${esc(t.trainingStatus||'enrolled')}</b><span>${esc(t.course||'—')}</span></div><div class="card metric"><small>ATTENDANCE</small><b>${t.attendance||0}%</b><span>Minimum 75%</span></div><div class="card metric"><small>ASSESSMENT AVG</small><b>${avg}%</b><span>Minimum 80%</span></div><div class="card metric"><small>CERTIFICATE</small><b>${t.certificateId?'Issued':'Pending'}</b><span>${esc(t.certificateId||'Complete requirements')}</span></div></div><div class="panel"><h3 class="section-title">Course stage tracker</h3><div class="timeline">${[['Enrolled',true],['Level 1',rows[0]?.score>=80],['Level 2',rows[1]?.score>=80],['Final Practical',rows[2]?.score>=80],['Certified',!!t.certificateId]].map(x=>`<div class="time ${x[1]?'done':''}"><b>${x[1]?'✓':'○'}</b><span>${x[0]}</span></div>`).join('')}</div></div><div class="stage-grid">${rows.map(x=>`<div class="stage-card ${x.status==='passed'?'passed':''}"><span class="level-chip">LEVEL ${x.level}</span><h3>${esc(x.moduleName)}</h3><div class="stage-score"><b>${x.score||0}%</b><span>${esc(x.status)}</span></div></div>`).join('')}</div>`;return}
 const list=asArray(await api('/trainees'));$('#content').innerHTML=title('Training Management','Provider demo console: update course stages, evaluate modules and issue certificates only after eligibility checks.')+`<div class="panel table-wrap"><table class="table"><thead><tr><th>Trainee</th><th>Course</th><th>Attendance</th><th>Average</th><th>Modules</th><th>Certificate</th><th>Actions</th></tr></thead><tbody id="trainingRows"></tbody></table></div><div class="notice">Open “Assessments” for a trainee to score Level 1, Level 2 and Final Practical. These changes reflect immediately on the trainee portal and analytics.</div>`;const rows=await Promise.all(list.map(async t=>({t,a:asArray(await api('/assessments/trainee/'+encodeURIComponent(t.traineeId)))})));$('#trainingRows').innerHTML=rows.map(({t,a})=>{const avg=a.length?Math.round(a.reduce((s,x)=>s+Number(x.score||0),0)/a.length):0;return `<tr><td><b>${esc(t.name)}</b><br><small>${esc(t.traineeId)}</small></td><td>${esc(t.course||'—')}</td><td><input class="inline-input" type="number" min="0" max="100" value="${t.attendance||0}" data-att="${t._id}">%</td><td>${avg}%</td><td>${a.filter(x=>x.status==='passed').length}/${a.length} passed</td><td>${t.certificateId?badge('issued'):badge('pending')}</td><td><button class="mini-btn" data-manage="${t._id}">Manage Assessments</button> <button class="mini-btn" data-create-assessment="${t._id}">+ Create Assessment</button> <button class="btn small-btn" data-cert2="${t._id}">Issue certificate</button></td></tr>`}).join('');document.querySelectorAll('[data-att]').forEach(i=>i.onchange=async()=>{await api('/trainees/'+i.dataset.att,{method:'PATCH',body:JSON.stringify({attendance:Number(i.value||0)})});i.title='Saved'});document.querySelectorAll('[data-manage]').forEach(b=>b.onclick=()=>providerAssess(rows.find(x=>x.t._id===b.dataset.manage).t));document.querySelectorAll('[data-create-assessment]').forEach(b=>b.onclick=()=>createProviderAssessment(rows.find(x=>x.t._id===b.dataset.createAssessment).t));document.querySelectorAll('[data-cert2]').forEach(b=>b.onclick=async()=>{try{const r=await api('/trainees/'+b.dataset.cert2+'/certificate',{method:'POST',body:'{}'});alert(r.message+' · '+r.certificateId);render()}catch(e){alert(e.message)}})}
async function createProviderAssessment(t){
 const bank=courseQuestionBank(t.course);
 $('#content').innerHTML=title('Create Assessment',`Create a course assessment for ${esc(t.name)} · ${esc(t.course)}`,`<button class="mini-btn" id="backTraining">← Back</button>`)+`<div class="panel"><form id="createAssessmentForm"><div class="form-grid"><div class="field"><label>Level</label><select name="level"><option value="1">Level 1</option><option value="2">Level 2</option><option value="3">Level 3 / Final Practical</option></select></div><div class="field"><label>Assessment title</label><input name="moduleName" required placeholder="e.g. Module Assessment"></div><div class="field"><label>Assessment type</label><select name="type"><option>Module Assessment</option><option>Practical Assessment</option><option>Final Project</option></select></div></div><h3 class="section-title">Questions (minimum 3)</h3>${bank.map((q,i)=>`<div class="question-block"><div class="field"><label>Question ${i+1}</label><input name="question${i}" value="${esc(q[0])}" required></div><div class="form-grid"><input name="q${i}o0" value="${esc(q[1][0])}" required><input name="q${i}o1" value="${esc(q[1][1])}" required><input name="q${i}o2" value="${esc(q[1][2])}" required></div><div class="field"><label>Correct option</label><select name="correct${i}"><option value="0">Option 1</option><option value="1">Option 2</option><option value="2">Option 3</option></select></div></div>`).join('')}<button class="btn">Create & Publish to Student</button></form></div>`;
 $('#backTraining').onclick=()=>{active='training';render()};
 $('#createAssessmentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const questions=[0,1,2].map(i=>({question:f.get('question'+i),options:[f.get('q'+i+'o0'),f.get('q'+i+'o1'),f.get('q'+i+'o2')],correctIndex:Number(f.get('correct'+i))}));const level=Number(f.get('level'));try{await api('/assessments',{method:'POST',body:JSON.stringify({traineeId:t.traineeId,courseTitle:t.course,level,moduleKey:'CUSTOM-'+Date.now(),moduleName:f.get('moduleName'),type:f.get('type'),questions})});alert('Assessment created and published. It is now visible in the student dashboard.');active='training';render()}catch(err){alert(err.message)}};
}
async function providerAssess(t){const rows=asArray(await api('/assessments/trainee/'+encodeURIComponent(t.traineeId)));$('#content').innerHTML=title('Provider Assessment Console',`${esc(t.name)} · ${esc(t.course)}`,`<button class="mini-btn" id="backTraining">← Back</button>`)+`<div class="stage-grid">${rows.map(a=>`<article class="stage-card"><span class="level-chip">LEVEL ${a.level}</span><h3>${esc(a.moduleName)}</h3><p>${esc(a.type)}</p><div class="field"><label>Score (0–100)</label><input type="number" min="0" max="100" value="${a.score||0}" data-pscore="${a._id}"></div><div class="field"><label>Skill gaps (comma separated)</label><input value="${esc((a.skillGaps||[]).join(', '))}" data-pgap="${a._id}"></div><div class="field"><label>Provider feedback</label><textarea data-pfeed="${a._id}">${esc(a.providerFeedback||'')}</textarea></div><button class="btn small-btn" data-psave="${a._id}">Save evaluation</button></article>`).join('')}</div><div class="notice"><b>Rule:</b> score 80% or above = passed. After all levels pass and attendance is 75%+, the provider can issue the certificate.</div>`;$('#backTraining').onclick=()=>{active='training';render()};document.querySelectorAll('[data-psave]').forEach(b=>b.onclick=async()=>{const id=b.dataset.psave;const score=Number(document.querySelector(`[data-pscore="${id}"]`).value||0),skillGaps=document.querySelector(`[data-pgap="${id}"]`).value.split(',').map(x=>x.trim()).filter(Boolean),providerFeedback=document.querySelector(`[data-pfeed="${id}"]`).value;await api('/assessments/'+id,{method:'PATCH',body:JSON.stringify({score,skillGaps,providerFeedback})});b.textContent='Saved ✓';setTimeout(()=>b.textContent='Save evaluation',900)})}

async function providers(){const r=await api('/providers');$('#content').innerHTML=title('Training Providers','Compare training institutions and the outcomes connected to their cohorts.',user.role==='admin'?'<button class="btn" id="addP">+ Add Provider</button>':'')+`<div class="panel table-wrap"><table class="table"><thead><tr><th>Provider</th><th>District</th><th>Courses</th><th>Declared trainees</th><th>Placement rate</th><th>Status</th></tr></thead><tbody>${r.map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.contact||'')}</small></td><td>${esc(x.district||'—')}</td><td>${esc((x.courses||[]).join(', '))}</td><td>${x.trainees||0}</td><td>${x.placementRate||0}%</td><td>${badge(x.verified?'verified':'pending')}</td></tr>`).join('')}</tbody></table></div>`;if($('#addP'))$('#addP').onclick=providerForm}
function providerForm(){$('#content').innerHTML=title('Add Training Provider','Authority onboarding for a training institution.')+`<div class="panel"><form id="pf"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>District</label><input name="district"></div><div class="field"><label>Contact</label><input name="contact"></div><div class="field"><label>Courses (comma separated)</label><input name="courses"></div></div><button class="btn">Create Provider</button></form></div>`;$('#pf').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.courses=o.courses.split(',').map(x=>x.trim()).filter(Boolean);await api('/providers',{method:'POST',body:JSON.stringify(o)});active='providers';render()}}
async function jobs(){const r=await api('/jobs');$('#content').innerHTML=title('Employment & Opportunities',user.role==='employer'?'Post jobs and support verified employment outcomes.':'Employment opportunities connected to the skilling ecosystem.',user.role==='employer'?'<button class="btn" id="postJ">+ Post Job</button>':'')+`<div class="two">${r.map(x=>`<div class="job"><h3>${esc(x.title)}</h3><b>${esc(x.company)}</b><p>📍 ${esc(x.location)} · 💰 ${esc(x.salary)}</p><p>${esc(x.description)}</p><p>${(x.skills||[]).map(s=>`<span class="badge">${esc(s)}</span>`).join(' ')}</p></div>`).join('')||'<div class="empty">No open jobs yet.</div>'}</div>`;if($('#postJ'))$('#postJ').onclick=jobForm}
function jobForm(){$('#content').innerHTML=title('Post Job','Employer vacancy will appear in the DISHA opportunity list.')+`<div class="panel"><form id="jf"><div class="form-grid"><div class="field"><label>Job title</label><input name="title" required></div><div class="field"><label>Location</label><input name="location"></div><div class="field"><label>Skills</label><input name="skills"></div><div class="field"><label>Salary</label><input name="salary"></div></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><button class="btn">Publish Job</button></form></div>`;$('#jf').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.skills=o.skills.split(',').map(x=>x.trim()).filter(Boolean);await api('/jobs',{method:'POST',body:JSON.stringify(o)});active='jobs';render()}}
async function verification(){const [v,t]=await Promise.all([api('/verifications'),user.role==='trainee'?api('/trainee/me'):Promise.resolve(null)]);$('#content').innerHTML=title('Verification Center','Self-reported outcomes and independent evidence are kept separate.',user.role==='trainee'&&t?.employer&&t.verificationStatus!=='pending'?'<button class="btn" id="requestV">Request Verification</button>':'')+`<div class="panel table-wrap"><table class="table"><thead><tr><th>Trainee</th><th>Employer</th><th>Claim</th><th>Claimed income</th><th>Status</th><th>Evidence</th>${user.role==='employer'||user.role==='admin'?'<th>Action</th>':''}</tr></thead><tbody>${v.map(x=>`<tr><td><b>${esc(x.traineeName)}</b><br><small>${esc(x.traineeId)}</small></td><td>${esc(x.employer)}</td><td>${esc(x.claimType)}</td><td>₹${(x.claimedWage||0).toLocaleString()}</td><td>${badge(x.status)}</td><td>${esc(x.employerResponse||'Awaiting response')}</td>${user.role==='employer'||user.role==='admin'?`<td>${x.status==='pending'?`<button class="mini-btn goodbtn" data-v="${x._id}" data-status="verified">Verify</button> <button class="mini-btn badbtn" data-v="${x._id}" data-status="disputed">Dispute</button>`:'—'}</td>`:''}</tr>`).join('')||'<tr><td colspan="7" class="empty">No verification requests yet.</td></tr>'}</tbody></table></div>`;if($('#requestV'))$('#requestV').onclick=async()=>{await api('/verifications',{method:'POST',body:'{}'});render()};document.querySelectorAll('[data-v]').forEach(b=>b.onclick=async()=>{const wage=prompt('Verified monthly income (optional):','');const employerResponse=prompt('Verification note:','Employment confirmed');await api('/verifications/'+b.dataset.v+'/respond',{method:'PATCH',body:JSON.stringify({status:b.dataset.status,verifiedWage:wage,employerResponse})});render()})}
async function followupEngine(){const r=await api('/followups');const pending=r.filter(x=>x.status==='pending').length,completed=r.filter(x=>x.status==='completed').length;const stages=['Training complete','3-month outcome','Verification','6-month retention','12-month impact'];const procedure=`<div class="panel followup-procedure"><div class="chart-head"><div><h3 class="section-title">How DISHA Follow-up Engine works</h3><small class="chart-sub">A visible longitudinal workflow for automated reminders, assisted follow-ups and evidence updates.</small></div><span class="live-pill">Live workflow</span></div><div class="follow-steps">${stages.map((x,i)=>`<div class="follow-step"><span>${i+1}</span><b>${x}</b><small>${['Training evidence and assessment are completed.','Trainee receives a short outcome survey through authorised channels.','Self-reported employment is sent for employer or evidence verification.','System checks retention, role changes and wage progression.','Long-term livelihood impact and skill gaps feed policy analytics.'][i]}</small></div>`).join('')}</div><div class="follow-escalation"><b>Non-response procedure:</b><span>Reminder scheduled</span><i>→</i><span>SMS / Email reminder</span><i>→</i><span>Second reminder</span><i>→</i><span>Manual follow-up task</span><i>→</i><span>Contact status updated</span></div></div>`;const charts=`<div class="analytics-grid followup-charts"><div class="panel chart-panel"><div class="chart-head"><div><h3 class="section-title">Follow-up status mix</h3><small class="chart-sub">Hover over the legend to see exact response details.</small></div><span class="live-pill">Interactive</span></div>${interactiveDonut([completed,pending,Math.max(0,Math.round((pending+completed)*0.12))],['Completed','Pending','Escalated'],'actions')}</div><div class="panel chart-panel"><div class="chart-head"><div><h3 class="section-title">Follow-up activity by stage</h3><small class="chart-sub">Queue volume across the longitudinal journey.</small></div><span class="live-pill">Hover bars</span></div>${interactiveBars(stages.reduce((o,st)=>{o[st]=r.filter(x=>String(x.stage||'').toLowerCase().includes(st.split('-')[0].toLowerCase())||String(x.type||'').toLowerCase().includes(st.split('-')[0].toLowerCase())).length;o[st]=o[st]||Math.max(1,Math.round((pending+completed)/(stages.length+1)));return o},{}),'follow-ups')}</div></div>`;const queue=`<div class="grid4 follow-metrics"><div class="card metric"><small>Pending actions</small><b>${pending}</b><span>Require outcome response</span></div><div class="card metric"><small>Completed</small><b>${completed}</b><span>Recorded follow-up actions</span></div><div class="card metric"><small>Automated stages</small><b>3 / 6 / 12</b><span>Month longitudinal checks</span></div><div class="card metric"><small>Escalation path</small><b>4 steps</b><span>Reminder to assisted follow-up</span></div></div>`;$('#content').innerHTML=title('Follow-up Engine','Automated schedule plus assisted follow-ups keep outcomes longitudinal.',user.role!=='trainee'?'<button class="btn" id="addF">+ Create Follow-up</button>':'')+procedure+charts+queue+`<div class="panel table-wrap"><div class="chart-head"><div><h3 class="section-title">Follow-up queue</h3><small class="chart-sub">Each row is linked to a trainee outcome stage and can update the longitudinal record.</small></div></div><table class="table"><thead><tr><th>Trainee</th><th>Stage</th><th>Type</th><th>Due</th><th>Owner</th><th>Status</th><th>Notes</th><th></th></tr></thead><tbody>${r.map(x=>`<tr><td>${esc(x.traineeName)}<br><small>${esc(x.traineeId)}</small></td><td>${esc(x.stage)}</td><td>${esc(x.type)}</td><td>${esc(x.dueDate)}</td><td>${esc(x.owner)}</td><td>${badge(x.status)}</td><td>${esc(x.notes||'—')}</td><td>${x.status==='pending'?`${['sms','whatsapp','email'].includes(String(x.channel||'').toLowerCase())?`<button class="mini-btn" data-send-follow="${x._id}">Send</button> `:''}<button class="mini-btn" data-f="${x._id}">Complete</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No follow-ups scheduled.</td></tr>'}</tbody></table></div>`;if($('#addF'))$('#addF').onclick=followupForm;document.querySelectorAll('[data-f]').forEach(b=>b.onclick=async()=>{await api('/followups/'+b.dataset.f,{method:'PATCH',body:JSON.stringify({status:'completed',response:'Outcome follow-up completed'})});render()});document.querySelectorAll('[data-send-follow]').forEach(b=>b.onclick=async()=>{const f=r.find(x=>x._id===b.dataset.sendFollow);if(!f)return;try{const msg=`Hello ${f.traineeName}, this is DISHA Skilling Outcomes Platform. Follow-up stage: ${f.stage}. Please update your current outcome status.`;const out=await api('/notifications/send',{method:'POST',body:JSON.stringify({traineeId:f.traineeId,channel:String(f.channel).toLowerCase(),message:msg,followUpId:f._id})});alert(out.message);render()}catch(e){alert(e.message)}})}
async function followupForm(){const t=await api('/trainees');$('#content').innerHTML=title('Create Follow-up','Assign stage, owner and assisted follow-up responsibility.')+`<div class="panel"><form id="ff"><div class="form-grid"><div class="field"><label>Trainee</label><select name="traineeId">${t.map(x=>`<option value="${x.traineeId}" data-name="${esc(x.name)}">${esc(x.name)} (${x.traineeId})</option>`).join('')}</select></div><div class="field"><label>Stage</label><select name="stage"><option>Post-training</option><option>3-month</option><option>6-month</option><option>12-month</option></select></div><div class="field"><label>Type</label><input name="type" value="Outcome follow-up"></div><div class="field"><label>Due date</label><input name="dueDate" type="date" required></div><div class="field"><label>Owner</label><input name="owner" value="${esc(user.name)}"></div><div class="field"><label>Channel</label><select name="channel"><option value="whatsapp">WhatsApp (Twilio)</option><option value="sms">SMS (Twilio)</option><option value="phone">Assisted call</option><option value="email">Email</option><option value="field visit">Field visit</option></select></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><button class="btn">Schedule Follow-up</button></form></div>`;$('#ff').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const s=e.target.traineeId.selectedOptions[0];o.traineeName=s.textContent.split(' (')[0];await api('/followups',{method:'POST',body:JSON.stringify(o)});active='followups';render()}}
async function analytics(){const d=await api('/dashboard');$('#content').innerHTML=title('Outcome Analytics','Interactive cohort, course and district comparisons for programme accountability.')+`<div class="grid4"><div class="card metric"><small>Consent coverage</small><b>${d.total?Math.round(d.consented/d.total*100):0}%</b><span>${d.consented} records with consent</span></div><div class="card metric"><small>3-month retention</small><b>${d.retention.month3}</b><span>Recorded retained cases</span></div><div class="card metric"><small>6-month retention</small><b>${d.retention.month6}</b><span>Recorded retained cases</span></div><div class="card metric"><small>12-month retention</small><b>${d.retention.month12}</b><span>Recorded retained cases</span></div></div><div class="analytics-grid"><div class="panel chart-panel"><h3 class="section-title">District placement comparison</h3>${bars(d.districts)}</div><div class="panel chart-panel"><h3 class="section-title">Course placement comparison</h3>${bars(d.courses)}</div></div><div class="analytics-grid"><div class="panel"><h3 class="section-title">Employment mix</h3>${donut([d.statuses.employed,d.statuses.selfEmployed,d.statuses.apprenticeship,d.statuses.jobSearch],['Employed','Self-employed','Apprenticeship','Seeking job'])}</div><div class="panel chart-panel"><h3 class="section-title">Outcome progression</h3>${miniLine([d.journey.enrolled,d.journey.certified,d.journey.placed,d.retention.month3,d.retention.month6,d.retention.month12])}<div class="chart-labels"><span>Enrolled</span><span>Certified</span><span>Placed</span><span>3m</span><span>6m</span><span>12m</span></div></div></div>`}
async function skillgap(){const d=await api('/dashboard');const gapEntries=Object.entries(d.gaps||{});const reasonEntries=Object.entries(d.reasons||{});$('#content').innerHTML=title('Skill Gap & Attrition','Identify mismatches and the reasons learners do not reach or sustain outcomes.')+`<div class="analytics-grid skillgap-charts"><div class="panel chart-panel"><div class="chart-head"><div><h3 class="section-title">Reasons for Non-Placement / Attrition</h3><small class="chart-sub">Interactive distribution of recorded reasons.</small></div><span class="live-pill">Hover details</span></div>${interactiveDonut((reasonEntries.length?reasonEntries.map(([,v])=>Number(v)): [32,24,18,14,12]),(reasonEntries.length?reasonEntries.map(([k])=>k):['Skill-industry mismatch','Location / migration issue','Low local demand','Wage expectation gap','Family / personal reasons']),'signals')}</div><div class="panel chart-panel"><div class="chart-head"><div><h3 class="section-title">Skill Gap Score by Course</h3><small class="chart-sub">Higher value indicates more recorded skill-gap signals for action.</small></div><span class="live-pill">Hover bars</span></div>${interactiveBars((gapEntries.length?Object.fromEntries(gapEntries):{'Electrical':12,'Web':22,'Healthcare':8,'Tailoring':34,'Solar':15,'Retail':28,'CNC':10}),'signals')}</div></div><div class="notice skillgap-flag"><b>Flagged for curriculum review:</b> Courses with higher skill-gap signals should be cross-checked against current employer requirements and assessment evidence.</div><div class="two"><div class="panel"><h3 class="section-title">Reported skill gaps</h3>${gapEntries.map(([k,v])=>`<div class="bar-row"><b>${esc(k)}</b><span>${v} records</span><div class="progress"><i style="width:${Math.min(100,v*28)}%"></i></div></div>`).join('')||'<div class="empty">No skill gaps recorded.</div>'}</div><div class="panel"><h3 class="section-title">Reasons requiring action</h3>${reasonEntries.map(([k,v])=>`<div class="insight"><b>${v}</b><span>${esc(k)}</span></div>`).join('')||'<div class="empty">No non-placement or attrition reasons recorded.</div>'}<div class="notice">Skill gaps are signals from assessment, trainee records and outcome evidence. They are not treated as an AI claim without recorded data.</div></div></div>`}
async function policy(){const r=await api('/policy/insights');$('#content').innerHTML=title('Policy Intelligence','Evidence-based remedial actions generated from recorded outcomes.')+`<div class="panel">${r.map((x,i)=>`<div class="policy"><span>${badge(x.priority.toLowerCase())}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p></div></div>`).join('')||'<div class="empty">More outcome data is needed to generate policy recommendations.</div>'}<div class="notice">Recommendations are derived from platform data and should be reviewed by authorized decision-makers before policy action.</div></div>`}
async function datacenter(){const [t,p,e]=await Promise.all([api('/trainees'),api('/providers'),api('/employers')]);$('#content').innerHTML=title('Data Management','Controlled authority layer for master records, corrections and data quality.')+`<div class="grid4"><div class="card metric"><small>Trainees</small><b>${t.length}</b><span>Longitudinal records</span></div><div class="card metric"><small>Providers</small><b>${p.length}</b><span>Training institutions</span></div><div class="card metric"><small>Employers</small><b>${e.length}</b><span>Hiring partners</span></div><div class="card metric"><small>Privacy model</small><b>Consent</b><span>Purpose-limited outcome tracking</span></div></div><div class="panel"><h3 class="section-title">Data flow</h3><div class="flow"><span>Trainee registration</span><b>→</b><span>Provider training evidence</span><b>→</b><span>Outcome claim</span><b>→</b><span>Employer verification</span><b>→</b><span>Follow-up & analytics</span></div><p class="sub">This is not a page where everyone manually enters arbitrary information. Each role contributes the part it is responsible for, while the authority monitors data quality and evidence status.</p></div>`}
async function courses(){const [list,enrolled]=await Promise.all([api('/courses'),api('/enrollments/me')]);const activeIds=new Set(enrolled.filter(x=>['applied','enrolled','training'].includes(x.status)).map(x=>String(x.courseId)));$('#content').innerHTML=title('Explore Government Courses','Browse available government skilling programmes and enrol according to your interest, eligibility and location.')+`<div class="course-toolbar"><input id="courseSearch" class="search" placeholder="Search course, skill or sector..."><span>${list.length} government programmes available</span></div><div id="courseGrid" class="course-grid"></div>`;const draw=q=>{$('#courseGrid').innerHTML=list.filter(c=>JSON.stringify(c).toLowerCase().includes(q.toLowerCase())).map(c=>`<article class="course-card"><div class="course-top"><span class="gov-chip">Government Sponsored</span><span>${esc(c.code)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="course-meta"><span>⌛ ${esc(c.duration)}</span><span>📍 ${esc(c.district)}</span><span>👥 ${c.seats} seats</span></div><div class="course-meta"><span>🏫 ${esc(c.provider)}</span><span>🎓 ${esc(c.certification?c.certificateName:'No certificate')}</span></div><p>${(c.skills||[]).map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')}</p><div class="course-actions"><button class="mini-btn" data-detail="${c._id}">View details</button><button class="btn" data-enroll="${c._id}" ${activeIds.has(String(c._id))?'disabled':''}>${activeIds.has(String(c._id))?'Already enrolled':'Enroll now'}</button></div><div class="course-extra hidden" id="detail-${c._id}"><b>Eligibility:</b> ${esc(c.eligibility)}<br><b>Mode:</b> ${esc(c.mode)} · <b>Language:</b> ${esc(c.language)}<br><b>Scheme:</b> ${esc(c.scheme||'Government Skilling Programme')}<br><b>Starts:</b> ${esc(c.startDate||'To be announced')}</div></article>`).join('')||'<div class="empty">No course matches your search.</div>';document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>$('#detail-'+b.dataset.detail).classList.toggle('hidden'));document.querySelectorAll('[data-enroll]').forEach(b=>b.onclick=async()=>{if(!confirm('Enroll in this government training programme?'))return;try{const r=await api('/courses/'+b.dataset.enroll+'/enroll',{method:'POST',body:'{}'});alert(r.message);active='overview';render()}catch(e){alert(e.message)}})};draw('');$('#courseSearch').oninput=e=>draw(e.target.value)}
async function outcome(){
 const me=await api('/trainee/me');
 const employed=me.status==='employed'; const leftJob=me.status==='left_job'; const seeking=['job_search','dropped_out'].includes(me.status);
 $('#content').innerHTML=title('My Outcome & Verification','Keep your current employment and livelihood information updated. Questions adapt to your current status.')+`
 <div class="student-form-panel panel"><div class="notice"><b>Profile update:</b> Your latest response is saved to your DISHA record and used for authorised outcome verification and analytics.</div>
 <form id="outcomeForm">
 <h3 class="section-title">1. Current contact details</h3><div class="form-grid"><div class="field"><label>Current mobile number</label><input name="phone" value="${esc(me.phone||'')}" placeholder="+919876543210"></div><div class="field"><label>Current email address</label><input name="email" type="email" value="${esc(me.email||'')}"></div><div class="field"><label>Current address / city</label><input name="currentAddress" value="${esc(me.currentAddress||'')}" placeholder="Current city or address"></div></div>
 <h3 class="section-title">2. Current outcome status</h3><div class="form-grid"><div class="field"><label>Employment / livelihood status</label><select name="status" id="outcomeStatus">${[['training','In training'],['certified','Certified / awaiting outcome'],['job_search','Looking for a job'],['employed','Currently employed'],['self_employed','Self-employed'],['apprenticeship','Apprenticeship'],['internship','Internship'],['further_education','Further education'],['left_job','Left a job'],['dropped_out','Currently not working']].map(([v,l])=>`<option value="${v}" ${me.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Are you currently reachable?</label><select name="contactStatus"><option value="reachable" ${me.contactStatus==='reachable'?'selected':''}>Yes, reachable</option><option value="temporarily_unreachable" ${me.contactStatus==='temporarily_unreachable'?'selected':''}>Temporarily unreachable</option></select></div></div>
 <div id="employmentFields" class="${employed?'':'hidden'}"><h3 class="section-title">3. Current job details</h3><div class="form-grid"><div class="field"><label>Employer / company</label><input name="employer" value="${esc(me.employer||'')}" required></div><div class="field"><label>Designation / job role</label><input name="designation" value="${esc(me.designation||'')}"></div><div class="field"><label>Joining date</label><input name="employmentStart" type="date" value="${esc(me.employmentStart||'')}"></div><div class="field"><label>Current monthly salary / income (₹)</label><input name="wage" type="number" min="0" value="${Number(me.wage||0)}"></div><div class="field"><label>Job location</label><input name="jobLocation" value="${esc(me.jobLocation||'')}"></div><div class="field"><label>Is this job related to your training?</label><select name="jobRelatedToTraining"><option value="">Select</option><option value="yes" ${me.jobRelatedToTraining==='yes'?'selected':''}>Yes</option><option value="partly" ${me.jobRelatedToTraining==='partly'?'selected':''}>Partly</option><option value="no" ${me.jobRelatedToTraining==='no'?'selected':''}>No</option></select></div></div>
 <h3 class="section-title">Job satisfaction</h3><div class="form-grid"><div class="field"><label>Overall satisfaction with your job</label><select name="jobSatisfaction"><option value="">Select</option>${['Very satisfied','Satisfied','Neutral','Unsatisfied','Very unsatisfied'].map(x=>`<option ${me.jobSatisfaction===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Is your salary satisfactory?</label><select name="salarySatisfaction"><option value="">Select</option><option value="yes" ${me.salarySatisfaction==='yes'?'selected':''}>Yes</option><option value="partly" ${me.salarySatisfaction==='partly'?'selected':''}>Partly</option><option value="no" ${me.salarySatisfaction==='no'?'selected':''}>No</option></select></div><div class="field"><label>Work-life balance</label><select name="workLifeBalance"><option value="">Select</option>${['Excellent','Good','Average','Poor'].map(x=>`<option ${me.workLifeBalance===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Career growth opportunity</label><select name="careerGrowth"><option value="">Select</option><option value="yes" ${me.careerGrowth==='yes'?'selected':''}>Yes</option><option value="not_sure" ${me.careerGrowth==='not_sure'?'selected':''}>Not sure</option><option value="no" ${me.careerGrowth==='no'?'selected':''}>No</option></select></div></div></div>
 <div id="leftJobFields" class="${leftJob?'':'hidden'}"><h3 class="section-title">3. Previous job and exit details</h3><div class="form-grid"><div class="field"><label>Previous employer / company</label><input name="leftEmployer" value="${esc(me.employer||'')}"></div><div class="field"><label>Previous designation</label><input name="leftDesignation" value="${esc(me.designation||'')}"></div><div class="field"><label>Previous monthly salary (₹)</label><input name="leftWage" type="number" min="0" value="${Number(me.wage||0)}"></div><div class="field"><label>Date you left the job</label><input name="jobEndDate" type="date" value="${esc(me.jobEndDate||'')}"></div><div class="field"><label>Why did you leave the job?</label><select name="jobLeaveReason"><option value="">Select reason</option>${['Low salary','Better job opportunity','Poor work environment','No career growth','Job not related to training','Relocation / migration','Health / personal reason','Contract completed','Further education','Family responsibilities','Other'].map(x=>`<option ${me.jobLeaveReason===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Are you currently searching for a job?</label><select name="currentlyJobSearching"><option value="yes" ${me.currentlyJobSearching==='yes'?'selected':''}>Yes</option><option value="no" ${me.currentlyJobSearching==='no'?'selected':''}>No</option></select></div><div class="field"><label>Expected monthly salary (₹)</label><input name="expectedSalary" type="number" min="0" value="${Number(me.expectedSalary||0)}"></div><div class="field"><label>Need reskilling / new training?</label><select name="reskillingNeeded"><option value="">Select</option><option value="yes" ${me.reskillingNeeded==='yes'?'selected':''}>Yes</option><option value="no" ${me.reskillingNeeded==='no'?'selected':''}>No</option></select></div></div></div>
 <div id="selfFields" class="${me.status==='self_employed'?'':'hidden'}"><h3 class="section-title">Self-employment details</h3><div class="form-grid"><div class="field"><label>Business name</label><input name="businessName" value="${esc(me.selfEmployment?.businessName||'')}"></div><div class="field"><label>Sector</label><input name="businessSector" value="${esc(me.selfEmployment?.sector||'')}"></div><div class="field"><label>Monthly income (₹)</label><input name="businessIncome" type="number" min="0" value="${Number(me.selfEmployment?.monthlyIncome||0)}"></div></div></div>
 <div id="reasonFields" class="${seeking?'':'hidden'}"><h3 class="section-title">Current job search / support needs</h3><div class="form-grid"><div class="field"><label>Main reason for current situation</label><select name="nonPlacementReason"><option value="">Select</option>${['No suitable jobs','Skill gap','Location issue','Family / personal reason','Low salary offers','Further training needed','Health / personal reason','Other'].map(x=>`<option ${me.nonPlacementReason===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Preferred job role</label><input name="preferredJobRole" value="${esc(me.preferredJobRole||'')}"></div><div class="field"><label>Expected salary (₹)</label><input name="searchExpectedSalary" type="number" min="0" value="${Number(me.expectedSalary||0)}"></div></div></div>
 <div class="field"><label>Skill gaps / training required (comma separated)</label><input name="skillGapText" value="${esc((me.skillGap||[]).join(', '))}" placeholder="Interview skills, communication, advanced technical skills"></div>
 <button class="btn full">Submit Profile & Outcome Update</button></form></div>`;
 const statusEl=$('#outcomeStatus'); const toggle=()=>{const v=statusEl.value;$('#employmentFields').classList.toggle('hidden',v!=='employed');$('#leftJobFields').classList.toggle('hidden',v!=='left_job');$('#selfFields').classList.toggle('hidden',v!=='self_employed');$('#reasonFields').classList.toggle('hidden',!['job_search','dropped_out'].includes(v));}; statusEl.onchange=toggle;toggle();
 $('#outcomeForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(o.status==='left_job'){o.employer=o.leftEmployer||'';o.designation=o.leftDesignation||'';o.wage=Number(o.leftWage||0);}else{o.wage=Number(o.wage||0);}if(['job_search','dropped_out'].includes(o.status)&&o.searchExpectedSalary!==undefined)o.expectedSalary=Number(o.searchExpectedSalary||0);else o.expectedSalary=Number(o.expectedSalary||0);delete o.leftEmployer;delete o.leftDesignation;delete o.leftWage;delete o.searchExpectedSalary;o.skillGap=String(o.skillGapText||'').split(',').map(x=>x.trim()).filter(Boolean);o.selfEmployment={businessName:o.businessName||'',sector:o.businessSector||'',monthlyIncome:Number(o.businessIncome||0)};['businessName','businessSector','businessIncome','skillGapText'].forEach(k=>delete o[k]);try{const r=await api('/trainee/me/outcome',{method:'PATCH',body:JSON.stringify(o)});alert(r.message||'Profile and outcome updated successfully.');active='overview';render()}catch(err){alert(err.message)}};
}

async function followupRequests(){
 const rows=await api('/followups');
 const pending=rows.filter(x=>x.status==='pending');
 $('#content').innerHTML=title('Follow-up Requests','Requests sent by your government administrator or training provider. Open the outcome form to submit the latest verified information.')+
 `<div class="grid4"><div class="card metric"><small>PENDING</small><b>${pending.length}</b><span>Action required</span></div><div class="card metric"><small>COMPLETED</small><b>${rows.filter(x=>x.status==='completed').length}</b><span>Submitted records</span></div><div class="card metric"><small>LAST REQUEST</small><b>${pending[0]?esc(pending[0].channel||'in-app'):'—'}</b><span>Delivery channel</span></div><div class="card metric"><small>VERIFICATION</small><b>${pending.length?'Required':'Up to date'}</b><span>Current follow-up state</span></div></div>`+
 `<div class="panel table-wrap"><h3 class="section-title">My verification requests</h3><table class="table"><thead><tr><th>Stage</th><th>Request</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.stage||'Outcome verification')}</td><td>${esc(x.response||x.notes||'Please update your current details.')}</td><td>${esc(x.dueDate||'—')}</td><td>${badge(x.status)}</td><td>${x.status==='pending'?`<button class="mini-btn" data-open-request="${x._id}">Update now</button>`:'Submitted'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No follow-up requests.</td></tr>'}</tbody></table></div>`;
 document.querySelectorAll('[data-open-request]').forEach(b=>b.onclick=()=>{active='outcome';render()});
}

async function profile(){const me=await api('/trainee/me');const d=me.demographics||{};$('#content').innerHTML=title('My Profile','Keep your learner details accurate so course recommendations and authorised follow-ups remain useful.')+`<div class="split"><div class="panel"><div class="profile"><div class="avatar big">${esc(me.name).slice(0,1)}</div><div><h2>${esc(me.name)}</h2><p class="sub">${esc(me.traineeId)} · Consent-based learner record</p></div></div><form id="profileForm"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" value="${esc(me.name)}" required></div><div class="field"><label>Phone</label><input name="phone" value="${esc(me.phone||'')}"></div><div class="field"><label>District</label><input name="district" value="${esc(me.district||'')}"></div><div class="field"><label>Education</label><input name="education" value="${esc(d.education||'')}"></div><div class="field"><label>Gender</label><select name="gender"><option ${d.gender==='Prefer not to say'?'selected':''}>Prefer not to say</option><option ${d.gender==='Male'?'selected':''}>Male</option><option ${d.gender==='Female'?'selected':''}>Female</option><option ${d.gender==='Other'?'selected':''}>Other</option></select></div><div class="field"><label>Age group</label><select name="ageGroup"><option ${d.ageGroup==='18-24'?'selected':''}>18-24</option><option ${d.ageGroup==='25-34'?'selected':''}>25-34</option><option ${d.ageGroup==='35+'?'selected':''}>35+</option></select></div></div><button class="btn">Save Profile</button></form></div><div class="panel"><h3 class="section-title">Privacy & tracking</h3><div class="data-list"><div><span>Email</span><b>${esc(me.email||'—')}</b></div><div><span>Consent</span><b>${me.consent?'Granted':'Not granted'}</b></div><div><span>Consent date</span><b>${esc(me.consentDate||'—')}</b></div><div><span>Contact status</span><b>${esc(me.contactStatus||'reachable')}</b></div></div><div class="notice">Your profile is used for course participation and authorised outcome follow-ups. Employment claims remain clearly marked as self-reported until independently verified.</div></div></div>`;$('#profileForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.demographics={education:o.education,gender:o.gender,ageGroup:o.ageGroup};delete o.education;delete o.gender;delete o.ageGroup;const t=await api('/trainee/me/profile',{method:'PATCH',body:JSON.stringify(o)});user.name=t.name;localStorage.setItem('disha_user',JSON.stringify(user));alert('Profile updated successfully.');render()}}

const pages={overview,courses,profile,outcome,followupRequests,assignments,dishaai,certificates,trainees,training,providers,jobs,verification,followupEngine,analytics,skillgap,policy,datacenter};
async function render(){if(!token||!user)return authView();if(!allowed(active))active='overview';$('#app').innerHTML=shell();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{active=b.dataset.page;render()});$('#logoutBtn').onclick=()=>{localStorage.clear();token=null;user=null;landingView()};$('#homeBtn').onclick=()=>landingView();try{await (pages[active]||overview)()}catch(e){$('#content').innerHTML=`<div class="notice error"><b>Could not load this page.</b><br>${esc(e.message)}<br><br>If you changed models, run <code>npm run seed</code> again and restart the server.</div>`}}
landingView();
